package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Unit tests for ReferenceType.getGenericSignature
 */
public class ReferenceType_getGenericSignature_TriageGen2Test {

    @Test
    public void testGetGenericSignature_Success() {
        // Arrange
        Class<?> cls = String.class;
        JavaType mockReferencedType = mock(JavaType.class);

        // We need to use the static factory method because the constructor is protected
        ReferenceType referenceType = ReferenceType.construct(cls, mockReferencedType, null, null);

        StringBuilder sb = new StringBuilder("Initial");

        // Mock the behavior of the referenced type's getGenericSignature
        // The method being tested calls: sb = _referencedType.getGenericSignature(sb);
        // where sb already has '<' appended.
        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder passedSb = invocation.getArgument(0);
            passedSb.append("MockedType");
            passedSb.append('>');
            return passedSb;
        });

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        // Expected flow: 
        // 1. _classSignature (appends class info, for String it's usually Ljava/lang/String;)
        // 2. sb.append('<')
        // 3. _referencedType.getGenericSignature(sb) -> appends "MockedType>"

        // Since we cannot easily predict exact _classSignature output without full context, 
        // we verify the sequence and the content added by the method logic itself.

        Assert.assertTrue(result.toString().contains("<"));
        Assert.assertTrue(result.toString().contains("MockedType"));
        Assert.assertTrue(result.toString().endsWith(">"));

        // Verify interaction with the referenced type
        verify(mockReferencedType).getGenericSignature(any(StringBuilder.class));
    }

    @Test
    public void testGetGenericSignature_EmptyStringBuilder() {
        // Arrange
        Class<?> cls = Object.class;
        JavaType mockReferencedType = mock(JavaType.class);
        ReferenceType referenceType = ReferenceType.construct(cls, mockReferencedType, null, null);

        StringBuilder sb = new StringBuilder();

        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder passedSb = invocation.getArgument(0);
            passedSb.append("Content");
            passedSb.append('>');
            return passedSb;
        });

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        // Check that '<' was appended before the referenced type call
        // The result should contain '<Content>' (or class signature + <Content>)
        String resultStr = result.toString();
        Assert.assertTrue("Result should contain '<'", resultStr.contains("<"));
        Assert.assertTrue("Result should contain 'Content'", resultStr.contains("Content"));
        Assert.assertTrue("Result should contain '>'", resultStr.contains(">"));
    }

    @Test(expected = NullPointerException.class)
    public void testGetGenericSignature_NullStringBuilder() {
        // Arrange
        Class<?> cls = Object.class;
        JavaType mockReferencedType = mock(JavaType.class);
        ReferenceType referenceType = ReferenceType.construct(cls, mockReferencedType, null, null);

        // Act
        referenceType.getGenericSignature(null);

        // Assert - Expect NullPointerException
    }
}
